"""Regression tests for the benchmark-only Layer-2 homography reference."""

from __future__ import annotations

import math
import unittest

import numpy as np

from AI_server.benchmark.layer2.reference_homography import (
    CANONICAL_CARDINAL_POINTS,
    InvalidGeometryError,
    build_image_to_mm_homography,
    physical_radius_mm,
    score_from_layer2_reference,
    transform_point_to_mm,
)


CANONICAL_IMAGE = {role: point for role, point in CANONICAL_CARDINAL_POINTS.items()}

# Values below are frozen from the independent Layer-2 analysis output, not
# generated by application scoring code. They exercise the actual consensus
# cardinals and authoritative consensus hole center for accepted sources.
REAL_FIXTURES = {
    "RIFLE_SRC_0532": {
        "cardinals": {"12h": (1530.0944530925, 1774.9557063873), "3h": (2040.5183924522, 2295.3958951407), "6h": (1521.1299364531, 2806.5509129431), "9h": (1008.9588182749, 2287.8249513412)},
        "hole": (1449.3422611343, 2279.2548136724), "expected": (-3.3673472417, -0.5203761889, 3.4073184213, 96),
    },
    "RIFLE_SRC_0559": {
        "cardinals": {"12h": (1605.8315284850, 1357.0152117922), "3h": (2034.6072233344, 2059.6010675989), "6h": (1551.5427800434, 2814.3262598866), "9h": (1061.1214832961, 2129.6090563519)},
        "hole": (1418.5458449459, 1940.1760140660), "expected": (-7.6102139054, -5.0079650949, 9.1101630104, 73),
    },
    "RIFLE_SRC_0587": {
        "cardinals": {"12h": (1446.6537355288, 1361.4413417004), "3h": (1957.7039010987, 2023.1319507424), "6h": (1462.2552254114, 2733.1983997762), "9h": (918.3614338547, 2078.3682073650)},
        "hole": (1345.9759645445, 2048.3576006448), "expected": (-4.7199539713, -0.2398938469, 4.7260463972, 91),
    },
}


class ReferenceHomographyTests(unittest.TestCase):
    def test_exact_canonical_identity_mapping(self):
        homography = build_image_to_mm_homography(CANONICAL_IMAGE)
        self.assertTrue(np.allclose(homography, np.eye(3), atol=1e-12))
        self.assertTrue(np.allclose(transform_point_to_mm(homography, (0.0, 0.0)), (0.0, 0.0), atol=1e-12))

    def test_translated_scaled_target(self):
        cardinals = {role: (x * 20 + 1000, y * 20 - 700) for role, (x, y) in CANONICAL_IMAGE.items()}
        homography = build_image_to_mm_homography(cardinals)
        self.assertTrue(np.allclose(transform_point_to_mm(homography, (1000, -700)), (0.0, 0.0), atol=1e-10))
        self.assertTrue(np.allclose(transform_point_to_mm(homography, (1050, -650)), (2.5, 2.5), atol=1e-10))

    def test_perspective_quadrilateral(self):
        cardinals = {"12h": (90, 15), "3h": (205, 105), "6h": (125, 240), "9h": (-20, 130)}
        homography = build_image_to_mm_homography(cardinals)
        for role, expected in CANONICAL_IMAGE.items():
            self.assertTrue(np.allclose(transform_point_to_mm(homography, cardinals[role]), expected, atol=1e-9))

    def test_transformed_target_center_is_origin(self):
        homography = build_image_to_mm_homography({"12h": (50, 0), "3h": (100, 50), "6h": (50, 100), "9h": (0, 50)})
        self.assertTrue(np.allclose(transform_point_to_mm(homography, (50, 50)), (0, 0), atol=1e-10))

    def test_known_physical_point_and_radius(self):
        homography = build_image_to_mm_homography(CANONICAL_IMAGE)
        point = transform_point_to_mm(homography, (3, 4))
        self.assertTrue(np.allclose(point, (3.0, 4.0), atol=1e-12))
        self.assertAlmostEqual(physical_radius_mm(point), 5.0, places=12)

    def test_exact_maximum_radius_is_a_hit(self):
        self.assertEqual(score_from_layer2_reference(25.0), 10)

    def test_radius_beyond_maximum_is_a_miss(self):
        self.assertEqual(score_from_layer2_reference(25.000001), 0)

    def test_invalid_degenerate_cardinals_are_rejected(self):
        with self.assertRaises(InvalidGeometryError):
            build_image_to_mm_homography({"12h": (0, 0), "3h": (1, 0), "6h": (2, 0), "9h": (3, 0)})

    def test_nan_and_inf_are_rejected(self):
        for bad in (float("nan"), float("inf")):
            with self.subTest(bad=bad), self.assertRaises(InvalidGeometryError):
                build_image_to_mm_homography({"12h": (0, bad), "3h": (1, 0), "6h": (0, 1), "9h": (-1, 0)})

    def test_semantic_role_ordering_matters(self):
        homography = build_image_to_mm_homography({"12h": (0, -10), "3h": (20, 0), "6h": (0, 10), "9h": (-20, 0)})
        self.assertTrue(np.allclose(transform_point_to_mm(homography, (20, 0)), (22.75, 0), atol=1e-9))
        swapped = {"12h": (0, 10), "3h": (20, 0), "6h": (0, -10), "9h": (-20, 0)}
        self.assertTrue(np.allclose(transform_point_to_mm(build_image_to_mm_homography(swapped), (0, -10)), (0, 22.75), atol=1e-9))

    def test_homography_inverse_exists_for_valid_geometry(self):
        inverse = np.linalg.inv(build_image_to_mm_homography({"12h": (10, 20), "3h": (80, 40), "6h": (50, 120), "9h": (-20, 90)}))
        self.assertTrue(np.all(np.isfinite(inverse)))

    def test_real_source_regression_fixtures(self):
        for source_id, fixture in REAL_FIXTURES.items():
            with self.subTest(source_id=source_id):
                x_expected, y_expected, radius_expected, score_expected = fixture["expected"]
                point = transform_point_to_mm(build_image_to_mm_homography(fixture["cardinals"]), fixture["hole"])
                # The historical analysis fixture was produced by OpenCV's
                # float32 transform; this independent float64 reference must
                # stay within 2 micrometres without hiding material drift.
                self.assertAlmostEqual(point[0], x_expected, delta=2e-6)
                self.assertAlmostEqual(point[1], y_expected, delta=2e-6)
                self.assertAlmostEqual(physical_radius_mm(point), radius_expected, delta=2e-6)
                self.assertEqual(score_from_layer2_reference(physical_radius_mm(point)), score_expected)

    def test_invalid_radius_is_rejected(self):
        for radius in (-0.1, math.nan, math.inf):
            with self.subTest(radius=radius), self.assertRaises(ValueError):
                score_from_layer2_reference(radius)


if __name__ == "__main__":
    unittest.main()
